import {createEngine,createProject,transform} from '@zge/sdk';
export const kinds=['relay-courier','orchard-counter','beacon-rescue'];
export async function projectFor(kind){const index=kinds.indexOf(kind);if(index<0)throw Error('unknown game');const p=createProject({id:kind,name:kind});const component=['cargo','harvest','rescue'][index],counter=['parcels','fruit','signals'][index];p.components[component]={schema:'zge.component.v1',label:component,fields:{[counter]:{type:'number',min:0}}};p.components.goal={schema:'zge.component.v1',label:'Objective',fields:{complete:{type:'boolean'}}};p.plugins=['project:data-rules'];p.rules=[{id:'movement',kind:'move',entity:'player',speed:3+index},{id:'collection',kind:'collect',entity:'player',target:'pickup',component,counter,radius:1},{id:'objective',kind:'goal',entity:'goal',component:'goal',property:'complete',sourceEntity:'player',sourceComponent:component,counter,threshold:1}];const e=await createEngine({project:p}),s=await e.loadWorld();s.createEntity({id:'player',name:'Player',components:{transform:transform(),mesh:{primitive:'sphere',color:'#68c4ad'},[component]:{[counter]:0}}});s.createEntity({id:'pickup',name:'Supply',components:{transform:transform({position:[2,0,0]}),mesh:{primitive:'cylinder',color:'#dcad64'}}});s.createEntity({id:'goal',name:'Objective',components:{goal:{complete:false},transform:transform({position:[4,0,0]}),mesh:{primitive:'box',color:'#718ecf'}}});const p2=e.exportProject();await e.dispose();return p2;}
